<?php require_once __DIR__.'/lib/inicio.php';exigir_sesion();$filtro=es_control()?'1=1':'c.id_distrito='.(int)usuario()['id_distrito'];$casos=bd()->query("SELECT c.*,d.numero_distrito FROM casos_actualizacion c JOIN distritos d ON d.id_distrito=c.id_distrito WHERE $filtro ORDER BY c.id_caso DESC")->fetch_all(MYSQLI_ASSOC);include 'encabezado.php';?><section class="tarjeta"><h1>Expedientes de actualización</h1><div class="acciones"><a class="boton" href="registrar.php">Registrar caso</a><?php if(!es_control()):?><a class="boton secundario" href="sin_casos.php">No se presentan casos</a><?php endif?></div></section><section class="tarjeta"><table><thead><tr><th>Folio</th><th>Distrito</th><th>Unidad Territorial</th><th>Tipo</th><th>Estado</th><th>Fecha</th><th>Acción</th></tr></thead><tbody><?php foreach($casos as $c):?><tr><td><?=h($c['folio'])?></td><td><?=h((string)$c['numero_distrito'])?></td><td><?=h($c['clave_ut'].' '.$c['nombre_ut'])?></td><td><?=h($c['tipo_caso']?:'Pendiente')?></td><td><span class="etiqueta"><?=h(etiqueta_estado($c['estado']))?></span></td><td><?=h($c['fecha_registro'])?></td><td><a href="caso.php?id=<?=$c['id_caso']?>">Abrir</a></td></tr><?php endforeach?></tbody></table></section><?php include 'pie.php';?>